(function(){
  function parseSize(s){
    s=String(s||'').trim();
    var m=s.match(/^([\d.]+)\s*([KMGT]?)B?$/i);
    if(!m) return parseFloat(s)||0;
    var n=parseFloat(m[1]), u=m[2].toUpperCase();
    var mul={'':1,'K':1024,'M':1024*1024,'G':1024*1024*1024,'T':1024*1024*1024*1024}[u]||1;
    return n*mul;
  }
  function aggregate(text){
    var lines=String(text||'').split(/\r?\n/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var top={};
    lines.forEach(function(l){
      var sp=l.split(/\s+/); if(sp.length<2) return;
      var path=sp[0], size=parseSize(sp[1]);
      var name=path.replace(/^[.\/]+/,'').split('/')[0]||path;
      top[name]=(top[name]||0)+size;
    });
    var entries=Object.keys(top).map(function(k){return {name:k, bytes:top[k]};});
    entries.sort(function(a,b){return b.bytes-a.bytes;});
    var total=entries.reduce(function(a,b){return a+b.bytes;},0);
    var max=entries.length?entries[0].bytes:1;
    entries.forEach(function(e){ e.pct= total? Math.round(e.bytes/total*100):0; var n=Math.min(40,Math.max(1,Math.round(e.bytes/max*40))); e.bar='█'.repeat(n)+'░'.repeat(40-n); });
    return {value:{entries:entries, total:total}};
  }
  var API={aggregate:aggregate, parseSize:parseSize};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__DustForge__=API;
})();
